"""Generate the browser/Node layout contract from reviewed production sources."""
from pathlib import Path
import argparse,json,hashlib,sys
R=Path(__file__).resolve().parents[2];sys.path.insert(0,str(R/'tools'))
from srwz.chinese_layout import load_layout_profiles,COMMON_PROTECTED_WORDS,FORBIDDEN_LINE_START_CHARACTERS,FORBIDDEN_LINE_END_CHARACTERS
from srwz.compact_scopes import STORY,BATTLE,FLOW_SYNOPSIS,VISIBLE
from srwz.text import CONTROL_NOTATION
N=R/'config/text-layout/native-scene-contracts.json';overrides=json.loads(N.read_text());width_evidence=json.loads((R/overrides['evidence']).read_text())
P=R/'config/text-layout/zh-layout-profiles.json';profiles=load_layout_profiles(P)
proof=R/'docs/issue-assets/prose-step-audit-20261026/layout-report.json';native=json.loads(proof.read_text())['scene_metrics']
scenes={}
for name,profile_id,width,height,step,line_step,columns,max_lines,kind,compact in [
 ('story','story_dialogue',21,12,21,14,23,3,'dialogue',STORY),
 ('battle','battle_subtitle',22,11,22,12,21,2,'dialogue',BATTLE),
 *[(name,'stage_scroll_overview' if m['flow'] else 'world_history_scroll' if name=='main_scroll' else 'sp_narration_scroll',m['width'],m['height'],m['step_x'],m['step_y'],25 if m['flow'] else 21,None,'prose',FLOW_SYNOPSIS if m['flow'] else dict(width=14,space=12,letter=12,digit=11,restore_width=m['width'],restore_space=m['step_x'],restore_height=m['height'])) for name,m in native.items()]]:
 if name in overrides['scenes']:
  columns=overrides['scenes'][name]['columns']
  assert columns*step==width_evidence['nativeWidthExamples'][name]['widthPx'],(name,'native width evidence mismatch')
 p=profiles[profile_id];assert p.default_advance_px==step,(name,p.default_advance_px,step)
 if kind=='dialogue':assert (p.first_line_maximum_width or p.maximum_width)==columns
 scenes[name]=dict(id=name,profileId=profile_id,kind=kind,width=width,height=height,step=step,lineStep=line_step,columns=columns,widthPx=columns*step,maxLines=max_lines,continuationIndent='　' if kind=='dialogue' else '',compact=compact,protectedTerms=sorted(set(p.unbroken_terms)|set(COMMON_PROTECTED_WORDS)),packing='max_width' if kind=='dialogue' else overrides['prose_policy']['packing'],protectWords=kind=='dialogue')
# Library body descriptors and reviewed body typography are independent of dialogue.
from srwz.library_typography import BODY_HEIGHTS
for domain,height in BODY_HEIGHTS.items():
 name='library_'+domain;p=profiles[name];step=p.default_advance_px
 scenes[name]=dict(id=name,profileId=name,kind='prose',width=step,height=height,step=step,lineStep=12 if domain=='robot' else 14,columns=p.maximum_width,widthPx=p.maximum_width*step,maxLines=None,continuationIndent='',compact=dict(width=14,space=12,letter=11 if domain=='robot' else 12,digit=10 if domain=='robot' else 11,restore_width=step,restore_space=step,restore_height=height),protectedTerms=[],packing='balanced_width',protectWords=False)
for name,variant in overrides['variants'].items():
 scenes[name]=dict(scenes[variant['base']],id=name,columns=variant['columns'],widthPx=variant['columns']*scenes[variant['base']]['step'])
files=[P,N,R/overrides['evidence'],proof,R/'tools/srwz/compact_scopes.py',R/'tools/srwz/library_typography.py',R/'tools/srwz/control_layout.py',R/'tools/srwz/text.py']
files += [R/'config/text-layout'/name for name in sorted({name for profile in json.loads(P.read_text())['profiles'].values() for name in profile.get('unbroken_terms_files',[])})]
d=dict(schemaVersion=1,scenes=scenes,resourceSceneOverrides={resource:name for name,v in overrides['variants'].items() for resource in v['resource_ids']},controls=CONTROL_NOTATION.pattern.replace(r'\A','^'),compactCharacters=VISIBLE,forbiddenStart=''.join(sorted(FORBIDDEN_LINE_START_CHARACTERS)),forbiddenEnd=''.join(sorted(FORBIDDEN_LINE_END_CHARACTERS)),sources={str(p.relative_to(R)):hashlib.sha256(p.read_bytes()).hexdigest()for p in files})
content='// Generated by tools/text_layout/export_js_contracts.py; do not edit.\nexport const contracts = '+json.dumps(d,ensure_ascii=False,separators=(',',':'))+';\n'
out=R/'shared/text-layout/contracts.mjs';ap=argparse.ArgumentParser();ap.add_argument('--check',action='store_true');args=ap.parse_args()
if args.check:
 assert out.read_text()==content,'JS contracts stale: run python3 tools/text_layout/export_js_contracts.py'
else:out.write_text(content)
print('JS scene contracts verified' if args.check else 'JS scene contracts generated')
